async function api(path,options={}){const headers={"Content-Type":"application/json",...options.headers};const t=token();if(t)headers.Authorization=`Bearer ${t}`;let response;try{response=await fetch(path,{...options,credentials:"same-origin",headers});}catch(cause){if(cause?.name==="AbortError")throw Object.assign(cause,{code:"CANCELLED_REQUEST"});const error=new Error("Network request failed");error.code="NETWORK_REQUEST_FAILED";error.cause=cause;throw error;}let body,parseSucceeded=true;try{body=await response.json();}catch{body={};parseSucceeded=false;}if(!response.ok){const error=new Error(body?.error?.message||body?.message||`Request failed (${response.status})`);error.code=response.status===401||response.status===403?"AUTH_REQUIRED":(body?.error?.code||body?.code||"REQUEST_FAILED");error.httpStatus=response.status;error.parseSucceeded=parseSucceeded;throw error;}if(!parseSucceeded){const error=new Error("Malformed response");error.code="MALFORMED_RESPONSE";error.httpStatus=response.status;error.parseSucceeded=false;throw error;}return body.data??body;}
