const goals={open:["Open goal",null],half_mile:["0.5 mile",804.672],one_mile:["1 mile",1609.344],two_miles:["2 miles",3218.688],five_k:["5K",5000],ten_k:["10K",10000],half_marathon:["Half marathon",21097.5],marathon:["Marathon",42195]};
function selectedGoal(){const type=$("goal").value,autoFinish=$("autoFinish").checked;if(type!=="custom"){const [label,distanceMeters]=goals[type];return{type,label,distanceMeters,autoFinish};}const raw=$("customDistance").value.trim();if(!/^(?:\d+\.?\d*|\.\d+)$/.test(raw))throw new Error("Enter a valid positive custom distance");const value=Number(raw),unit=$("customUnit").value,distanceMeters=value*(unit==="miles"?1609.344:1000);if(!Number.isFinite(distanceMeters)||distanceMeters<100||distanceMeters>200000)throw new Error("Custom distance must be between 0.1 km and 200 km");return{type:"custom",label:`${value} ${unit==="miles"?"mi":"km"}`,distanceMeters,customValue:value,customUnit:unit,autoFinish};}
