function updateGoal(){const g=session?.goal;ui.goalProgress.hidden=!g?.distanceMeters;if(!g?.distanceMeters)return;const pct=Math.min(100,(session.distance/g.distanceMeters)*100);ui.goalLabel.textContent=`Goal: ${g.label}`;ui.goalCompleted.textContent=fmtDist(session.distance);ui.goalRemaining.textContent=fmtDist(Math.max(0,g.distanceMeters-session.distance));ui.goalPercent.textContent=`${Math.floor(pct)}%`;ui.goalBar.value=pct;}
function hav(a,b){const r=Math.PI/180,dLat=(b.latitude-a.latitude)*r,dLon=(b.longitude-a.longitude)*r,q=Math.sin(dLat/2)**2+Math.cos(a.latitude*r)*Math.cos(b.latitude*r)*Math.sin(dLon/2)**2;return 6371000*2*Math.atan2(Math.sqrt(q),Math.sqrt(1-q));}
