async function persistSamples(){if(session)await recoveryStore.save({...session,samples:session.samples.slice(-2000)});}
ui.start.onclick=async()=>{transientState="requesting_permission";watchError=false;lastQuality="";ui.status.textContent="Requesting precise location permission…";render();try{await tracker.requestPermission();operationalEvent("permission_granted");const now=Date.now();const goal=selectedGoal();if(selectedPlannedRoute)await api("/api/me/greatness/activities/start-with-route",{method:"POST",body:JSON.stringify({goal,selectedRoute:selectedPlannedRoute})});session={clientSessionId:crypto.randomUUID(),activityType:ui.activity.value,goal,selectedRoute:selectedPlannedRoute,state:"waiting_for_gps",startedAt:now,pausedAt:0,pausedMs:0,distance:0,samples:[],segments:[],baseline:null,milestones:{}};tracker.start(addSample,()=>{watchError=true;ui.status.textContent="GPS is unavailable. Move outdoors and wait, or cancel and try again.";render();});operationalEvent("recording_started");ui.status.textContent="Permission granted. Waiting for an accurate GPS sample…";timer=setInterval(()=>{render();persistSamples();},1000);render();}catch(error){session=null;transientState="permission_denied";operationalEvent("permission_denied");ui.status.textContent=error.message?.startsWith("Custom distance")||error.message?.startsWith("Enter a valid")?error.message:"Location permission was not granted. Enable location in browser settings, then try Start again.";render();}};
