function resume(){operationalEvent("recording_resumed");session.pausedMs+=Date.now()-session.pausedAt;session.pausedAt=0;session.baseline=null;session.state="active";tracker.start(addSample,()=>{watchError=true;render();});ui.status.textContent="Resumed with a fresh GPS baseline; the interruption gap will not be bridged.";timer ||= setInterval(render,1000);render();}ui.resume.onclick=resume;
