function summary(a){if(!a||typeof a!=="object"||!a.activityId||!Number.isFinite(Number(a.distanceMeters)))throw new Error("INVALID_ACTIVITY_RESPONSE");const valid=a.validation?.state==="valid";ui.summary.hidden=false;ui.summary.className=`card ${valid?"":"invalid"}`;ui.summary.innerHTML=`<h2>Completed ${safeActivityType(a.activityType)}</h2><p><strong>${fmtDist(a.distanceMeters)}</strong> · ${fmtTime(a.movingTimeMs)} moving · ${fmtTime(a.elapsedTimeMs)} elapsed · ${fmtTime(a.pausedTimeMs)} paused</p><p>Average pace: ${pace(a.movingTimeMs,a.distanceMeters)} · GPS: ${a.gpsQuality.rating} (${a.gpsQuality.acceptedSamples} accepted, ${a.gpsQuality.rejectedSamples} rejected)</p><p><strong>${valid?"Valid and verified":"Not verified"}</strong>${valid?"":" — excluded from records and challenges."} Save status: saved.</p><p>Personal records: ${a.personalRecordsEarned?.join(", ")||"None"}. Greatness Marks: ${a.achievementIds?.length||0}. Challenge contributions: ${a.challengeContributionIds?.length||0}.${a.goal?.distanceMeters?` Goal: ${escapeHtml(a.goal.label)} (${a.goal.completed?"completed":"not completed"}).`:""} Community sharing: ${a.privacy.activityVisibleToCommunity?"eligible under membership preferences":"private"}.</p>`;}
ui.finish.onclick=async()=>{if(finishing)return;if(session.state==="save_failed")operationalEvent("save_retried");finishing=true;session.state="finishing";operationalEvent("recording_finished");tracker.stop();clearInterval(timer);const t=snapshot();ui.syncState.textContent="Sync status: Saving…";render();try{const gps={rating:quality().replace(" GPS","").toLowerCase().replace("strong","excellent").replace("acquiring","unavailable"),acceptedSamples:session.samples.filter(x=>x.accepted).length,rejectedSamples:session.samples.filter(x=>!x.accepted).length,suspiciousMovementDetected:session.samples.some(x=>x.rejectionReason==="implausible_movement")};const a=await api("/api/me/greatness/activities",{method:"POST",body:JSON.stringify({clientSessionId:session.clientSessionId,activityType:session.activityType,startedAt:new Date(session.startedAt).toISOString(),endedAt:new Date().toISOString(),elapsedTimeMs:t.elapsed,movingTimeMs:t.moving,pausedTimeMs:t.paused,distanceMeters:session.distance,goal:session.goal,selectedRoute:session.selectedRoute,samples:session.samples,gpsQuality:gps})});session.state="completed";transientState="completed";ui.syncState.textContent=a.duplicateCompletion?"Sync status: Already saved":"Sync status: Saved";localStorage.removeItem(KEY);summary(a);ui.status.textContent="Activity saved to Your Greatness Journey.";session=null;await loadAll();}catch(error){session.state="save_failed";operationalEvent("save_failed");ui.syncState.textContent="Sync status: Retry required";console.warn("Greatness activity save failed",{clientSessionId:session.clientSessionId,errorCode:error?.message==="INVALID_ACTIVITY_RESPONSE"?"INVALID_ACTIVITY_RESPONSE":"REQUEST_FAILED"});ui.status.textContent="We could not save this activity. Your recording is retained. Finish retries the same session safely.";}finally{finishing=false;render();}};
