async function loadAll(){try{const j=await api("/api/me/greatness/journey");$("journeyStats").innerHTML=`<strong>Lifetime distance: ${fmtDist(j.lifetimeDistanceMeters)}</strong><p>${Object.keys(j.personalBests).length} personal records · ${j.achievements.length} Greatness Marks</p>`;$("activityList").innerHTML=j.activities.length?j.activities.map(a=>`<button class="activity" data-id="${a.activityId}">${safeActivityType(a.activityType)} · ${fmtDist(a.distanceMeters)} · ${new Date(a.endedAt).toLocaleDateString()} · ${a.verificationLevel}${a.goal?.distanceMeters?` · Goal: ${escapeHtml(a.goal.label)}`:""}${a.personalRecordsEarned?.length?" · Personal record":""} · ${a.privacy.activityVisibleToCommunity?"community eligible":"private"}</button>`).join(""):"<p>No activity history yet. Start your first movement.</p>";document.querySelectorAll(".activity").forEach(b=>b.onclick=()=>detail(b.dataset.id));membershipCard(j.membership);}catch(e){$("activityList").innerHTML=`<p>Journey unavailable: ${e.message}</p>`;}try{const {challenges}=await api("/api/me/greatness/challenges");$("challengeList").innerHTML=challenges.length?challenges.map(c=>`<article class="card"><h3>${c.name}</h3><p>${c.progress.toFixed?.(0)??c.progress} / ${c.target} · ${c.completed?"Completed":"In progress"}</p><p>${new Date(c.startsAt).toLocaleDateString()} – ${new Date(c.endsAt).toLocaleDateString()} · ${c.verificationRequirements}</p>${c.enrolled?"<strong>Enrolled</strong>":`<button data-enroll="${c.challengeId}">Enroll</button>`}</article>`).join(""):"<p>No challenges available.</p>";document.querySelectorAll("[data-enroll]").forEach(b=>b.onclick=async()=>{await api(`/api/me/greatness/challenges/${b.dataset.enroll}/enrollment`,{method:"POST"});loadAll();});}catch(e){$("challengeList").innerHTML=`<p>Challenges unavailable: ${e.message}</p>`;}}
