async function detail(id){try{const [a,r]=await Promise.all([api(`/api/me/greatness/activities/${id}`),api(`/api/me/greatness/activities/${id}/route`)]);$("activityDetail").innerHTML=`<article class="card"><h3>Activity details</h3><p>${fmtDist(a.distanceMeters)} · ${fmtTime(a.movingTimeMs)} · ${a.validation.state} · ${a.verificationLabel} · route ${r.visibility}${a.goal?.distanceMeters?` · Goal: ${escapeHtml(a.goal.label)} (${a.goal.completed?"completed":"not completed"})`:""}</p><p>Mile splits: ${a.splits.miles.map(s=>`${s.index}: ${fmtTime(s.durationMs)}${s.complete?"":" partial"}`).join(", ")||"None"}</p><p>Kilometer splits: ${a.splits.kilometers.map(s=>`${s.index}: ${fmtTime(s.durationMs)}${s.complete?"":" partial"}`).join(", ")||"None"}</p><canvas id="route" aria-label="Private route preview"></canvas><button id="deleteActivity" class="danger">Delete activity</button></article>`;drawRoute(r.points||[]);$("deleteActivity").onclick=async()=>{if(!confirm("Delete this activity? Challenge progress and records will be recalculated."))return;await api(`/api/me/greatness/activities/${id}`,{method:"DELETE"});$("activityDetail").innerHTML="<p>Activity deleted.</p>";await loadAll();await loadCommunity();};}catch(e){$("activityDetail").innerHTML=`<p>Activity unavailable: ${e.message}</p>`;}}
function drawRoute(points){const c=$("route"),ctx=c.getContext("2d");c.width=c.clientWidth*devicePixelRatio;c.height=c.clientHeight*devicePixelRatio;if(points.length<2){ctx.fillStyle="#c3d6cf";ctx.fillText("Route preview unavailable",20,30);return;}const xs=points.map(p=>p.longitude),ys=points.map(p=>p.latitude),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);ctx.strokeStyle="#f1c963";ctx.lineWidth=4;ctx.beginPath();points.forEach((p,i)=>{const x=20+(p.longitude-minX)/(maxX-minX||1)*(c.width-40),y=20+(maxY-p.latitude)/(maxY-minY||1)*(c.height-40);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();}
