  if(trailSearchLoading)return;
  const sequence=++trailSearchSequence;
  const secure=window.isSecureContext===true;
  trailDiagnostic("secure_context_detected",{secure});
  const geolocationAvailable=Boolean(navigator.geolocation?.getCurrentPosition);
  trailDiagnostic("navigator_geolocation_available",{available:geolocationAvailable});
  if(!secure){$("trailStatus").textContent="Location requires a secure HTTPS connection.";return;}
  if(!geolocationAvailable){$("trailStatus").textContent="Location is unavailable on this device. Activity recording remains available.";return;}
  // A new controller belongs only to this tap. Geolocation itself is never tied to it,
  // so Safari's permission sheet cannot abort the request.
  trailController=new AbortController();
  const controller=trailController;
  trailSearchLoading=true;
  $("findTrails").disabled=true;
  $("trailStatus").setAttribute("aria-busy","true");
  $("trailStatus").textContent="Requesting location for this search…";
  $("cancelTrailSearch").hidden=false;
  $("cancelTrailSearch").onclick=()=>{if(sequence!==trailSearchSequence)return;trailDiagnostic("request_cancelled",{phase:"user"});controller.abort();trailSearchSequence++;trailSearchLoading=false;trailController=null;$("findTrails").disabled=false;$("trailStatus").setAttribute("aria-busy","false");$("trailStatus").textContent="Trail search cancelled. Activity recording remains available.";$("cancelTrailSearch").hidden=true;};
