      let response;try{response=await fetch(path,{method:"POST",signal:controller.signal,credentials:"same-origin",cache:"no-store",headers,body:JSON.stringify({latitude:position.coords.latitude,longitude:position.coords.longitude,radiusMeters:Number($("trailRadius").value),limit:15})});}catch(cause){recordTrailRequestSnapshot({...snapshot,parserResult:"fetch failed",validationResult:"network request must complete"});if(cause?.name==="AbortError")throw cause;throw Object.assign(new Error("Network request failed"),{code:"NETWORK_REQUEST_FAILED",cause});}
